{-| @Backend.Runtime.Kernel.Binary — the `Std.Binary` writer and reader over `Node` boxes, in the wire form `Pudu.Eval.Binary` defines. -}
module Pudu.Backend.Runtime.Kernel.Binary (binaryKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. The thirteen
    integers a writer or reader takes are the `Node` variants' indexes in the
    order Whole, Real, Flag, Text, Raw, Reals, Items, Absent, Present, Fields,
    Choice, Record, Picked. -}
binaryKernelParts :: [(Text, [Text], [Text])]
binaryKernelParts =
  [ ("binary_wire", ["memory_failure"],
      [ "/* A name's hash, byte comparison, and scratch allocation. */"
      , "static uint64_t pudu_binary_hash(const unsigned char *b, size_t length) {"
      , "  uint64_t hash = UINT64_C(0xcbf29ce484222325);"
      , "  for (size_t i = 0; i < length; ++i) hash = (hash ^ b[i]) * UINT64_C(0x100000001b3);"
      , "  return hash;"
      , "}"
      , "static int pudu_binary_same(const unsigned char *a, size_t left, const unsigned char *b, size_t right) {"
      , "  return left == right && (left == 0 || memcmp(a, b, left) == 0);"
      , "}"
      , "static void *pudu_binary_grow(void *held, size_t count, size_t width) {"
      , "  void *grown;"
      , "  if (count > SIZE_MAX / width) pudu_memory_failure();"
      , "  grown = realloc(held, (count == 0 ? 1 : count) * width);"
      , "  if (grown == NULL) pudu_memory_failure();"
      , "  return grown;"
      , "}"
      ])
  , ("binary_encode", ["binary_wire", "array", "tree_walk", "text_allocate", "bytes_wrap", "magnitude"],
      [ "static inline void pudu_binary_store(unsigned char *at, uint32_t value) {"
      , "  for (int i = 0; i < 4; ++i) at[i] = (unsigned char)(value >> (8 * i));"
      , "}"
      , "/* The nodes written so far, the names in first-use order with a hash"
      , "   table over them, and which record last held each name. */"
      , "typedef struct {"
      , "  unsigned char *bytes; size_t length, capacity;"
      , "  pudu_text *names; size_t named, room;"
      , "  uint32_t *slots; size_t slotted;"
      , "  size_t *seen; size_t record;"
      , "  int tags[13]; int failed;"
      , "} pudu_binary_writer;"
      , "static void pudu_binary_put(pudu_binary_writer *out, const void *bytes, size_t length) {"
      , "  if (length > SIZE_MAX - out->length) pudu_memory_failure();"
      , "  if (out->length + length > out->capacity) {"
      , "    size_t capacity = out->capacity < 64 ? 64 : out->capacity;"
      , "    while (capacity < out->length + length) capacity = capacity > SIZE_MAX / 2 ? out->length + length : capacity * 2;"
      , "    out->bytes = pudu_binary_grow(out->bytes, capacity, 1);"
      , "    out->capacity = capacity;"
      , "  }"
      , "  if (length != 0) memcpy(out->bytes + out->length, bytes, length);"
      , "  out->length += length;"
      , "}"
      , "static void pudu_binary_put_byte(pudu_binary_writer *out, unsigned char byte) { pudu_binary_put(out, &byte, 1); }"
      , "static void pudu_binary_put_word(pudu_binary_writer *out, uint32_t value) {"
      , "  unsigned char bytes[4];"
      , "  pudu_binary_store(bytes, value);"
      , "  pudu_binary_put(out, bytes, 4);"
      , "}"
      , "static void pudu_binary_put_wide(pudu_binary_writer *out, uint64_t value) {"
      , "  unsigned char bytes[8];"
      , "  for (int i = 0; i < 8; ++i) bytes[i] = (unsigned char)(value >> (8 * i));"
      , "  pudu_binary_put(out, bytes, 8);"
      , "}"
      , "/* A length and its bytes; one past 32 bits fails the write. */"
      , "static void pudu_binary_put_bytes(pudu_binary_writer *out, pudu_text bytes) {"
      , "  if (bytes.length > UINT32_MAX) { out->failed = 1; return; }"
      , "  pudu_binary_put_word(out, (uint32_t)bytes.length);"
      , "  pudu_binary_put(out, bytes.bytes, bytes.length);"
      , "}"
      , "/* A name's index in the table, entering it on first use. The table"
      , "   borrows the name: the node tree outlives the write. */"
      , "static uint32_t pudu_binary_intern(pudu_binary_writer *out, pudu_text name) {"
      , "  size_t at;"
      , "  if (out->named * 2 >= out->slotted) {"
      , "    size_t wider = out->slotted < 16 ? 16 : out->slotted * 2;"
      , "    uint32_t *slots = calloc(wider, sizeof *slots);"
      , "    if (slots == NULL) pudu_memory_failure();"
      , "    for (size_t i = 0; i < out->named; ++i) {"
      , "      at = (size_t)pudu_binary_hash(out->names[i].bytes, out->names[i].length) & (wider - 1);"
      , "      while (slots[at] != 0) at = (at + 1) & (wider - 1);"
      , "      slots[at] = (uint32_t)i + 1;"
      , "    }"
      , "    free(out->slots);"
      , "    out->slots = slots;"
      , "    out->slotted = wider;"
      , "  }"
      , "  at = (size_t)pudu_binary_hash(name.bytes, name.length) & (out->slotted - 1);"
      , "  while (out->slots[at] != 0) {"
      , "    pudu_text held = out->names[out->slots[at] - 1];"
      , "    if (pudu_binary_same(held.bytes, held.length, name.bytes, name.length)) return out->slots[at] - 1;"
      , "    at = (at + 1) & (out->slotted - 1);"
      , "  }"
      , "  if (out->named >= UINT32_MAX || name.length > UINT32_MAX) { out->failed = 1; return 0; }"
      , "  if (out->named == out->room) {"
      , "    out->room = out->room < 16 ? 16 : out->room * 2;"
      , "    out->names = pudu_binary_grow(out->names, out->room, sizeof *out->names);"
      , "    out->seen = pudu_binary_grow(out->seen, out->room, sizeof *out->seen);"
      , "  }"
      , "  out->names[out->named] = name;"
      , "  out->seen[out->named] = 0;"
      , "  out->slots[at] = (uint32_t)out->named + 1;"
      , "  out->named += 1;"
      , "  return (uint32_t)(out->named - 1);"
      , "}"
      , "static void pudu_binary_node(pudu_binary_writer *out, pudu_box *node, int depth);"
      , "/* Fields written as name and node pairs; a name written twice in one"
      , "   list fails the write. Each name's earlier mark is put back at the end,"
      , "   so an enclosing list still knows its own names. */"
      , "static void pudu_binary_pairs(pudu_binary_writer *out, pudu_box *pairs, int depth) {"
      , "  pudu_items *items = pairs->fields[0].items;"
      , "  size_t record = ++out->record, held = 0;"
      , "  size_t *names, *before;"
      , "  if (items->length > UINT32_MAX) { out->failed = 1; return; }"
      , "  pudu_binary_put_word(out, (uint32_t)items->length);"
      , "  names = pudu_binary_grow(NULL, items->length, sizeof *names);"
      , "  before = pudu_binary_grow(NULL, items->length, sizeof *before);"
      , "  for (size_t i = 0; !out->failed && i < items->length; ++i) {"
      , "    pudu_box *pair = items->cells[i].box;"
      , "    uint32_t index = pudu_binary_intern(out, pair->fields[0].text);"
      , "    if (out->failed) break;"
      , "    if (out->seen[index] == record) { out->failed = 1; break; }"
      , "    names[held] = index;"
      , "    before[held] = out->seen[index];"
      , "    held += 1;"
      , "    out->seen[index] = record;"
      , "    pudu_binary_put_word(out, index);"
      , "    pudu_binary_node(out, pair->fields[1].box, depth + 1);"
      , "  }"
      , "  while (held > 0) { held -= 1; out->seen[names[held]] = before[held]; }"
      , "  free(names);"
      , "  free(before);"
      , "}"
      , "/* A map's fields in key order; its keys are already distinct. */"
      , "static void pudu_binary_keyed(pudu_binary_writer *out, pudu_box *map, int depth) {"
      , "  size_t count = pudu_tree_size(map->fields[0].tree);"
      , "  pudu_tree_node **nodes;"
      , "  if (count > UINT32_MAX) { out->failed = 1; return; }"
      , "  pudu_binary_put_word(out, (uint32_t)count);"
      , "  nodes = pudu_tree_nodes(map->fields[0].tree);"
      , "  for (size_t i = 0; !out->failed && i < count; ++i) {"
      , "    uint32_t index = pudu_binary_intern(out, nodes[i]->key.text);"
      , "    if (out->failed) break;"
      , "    pudu_binary_put_word(out, index);"
      , "    pudu_binary_node(out, nodes[i]->value.box, depth + 1);"
      , "  }"
      , "  free(nodes);"
      , "}"
      , "static void pudu_binary_node(pudu_binary_writer *out, pudu_box *node, int depth) {"
      , "  int kind = 0;"
      , "  pudu_text bytes;"
      , "  uint32_t index;"
      , "  if (depth > 512 || node == NULL) { out->failed = 1; return; }"
      , "  while (kind < 13 && out->tags[kind] != node->fields[0].scalar) kind += 1;"
      , "  switch (kind) {"
      , "    case 0: {"
      , "      pudu_int whole = node->fields[1].integer;"
      , "      uint64_t limit = (uint64_t)INT64_MAX + (whole.negative != 0);"
      , "      if (pudu_magnitude(whole) > limit) { out->failed = 1; break; }"
      , "      pudu_binary_put_byte(out, 0);"
      , "      pudu_binary_put_wide(out, whole.bits);"
      , "      break;"
      , "    }"
      , "    case 1: pudu_binary_put_byte(out, 1); pudu_binary_put_wide(out, node->fields[1].floating); break;"
      , "    case 2: pudu_binary_put_byte(out, 2); pudu_binary_put_byte(out, node->fields[1].scalar ? 1 : 0); break;"
      , "    case 3: pudu_binary_put_byte(out, 3); pudu_binary_put_bytes(out, node->fields[1].text); break;"
      , "    case 4: pudu_binary_put_byte(out, 4); pudu_binary_put_bytes(out, node->fields[1].box->fields[0].text); break;"
      , "    case 5:"
      , "      bytes = node->fields[1].box->fields[0].text;"
      , "      if (bytes.length % 8 != 0 || bytes.length / 8 > UINT32_MAX) { out->failed = 1; break; }"
      , "      pudu_binary_put_byte(out, 5);"
      , "      pudu_binary_put_word(out, (uint32_t)(bytes.length / 8));"
      , "      pudu_binary_put(out, bytes.bytes, bytes.length);"
      , "      break;"
      , "    case 6: {"
      , "      pudu_items *items = node->fields[1].box->fields[0].items;"
      , "      if (items->length > UINT32_MAX) { out->failed = 1; break; }"
      , "      pudu_binary_put_byte(out, 6);"
      , "      pudu_binary_put_word(out, (uint32_t)items->length);"
      , "      for (size_t i = 0; !out->failed && i < items->length; ++i) pudu_binary_node(out, items->cells[i].box, depth + 1);"
      , "      break;"
      , "    }"
      , "    case 7: pudu_binary_put_byte(out, 7); break;"
      , "    case 8: pudu_binary_put_byte(out, 8); pudu_binary_node(out, node->fields[1].box, depth + 1); break;"
      , "    case 9: pudu_binary_put_byte(out, 9); pudu_binary_pairs(out, node->fields[1].box, depth); break;"
      , "    case 11: pudu_binary_put_byte(out, 9); pudu_binary_keyed(out, node->fields[1].box, depth); break;"
      , "    case 10: case 12:"
      , "      index = pudu_binary_intern(out, node->fields[1].text);"
      , "      if (out->failed) break;"
      , "      pudu_binary_put_byte(out, 10);"
      , "      pudu_binary_put_word(out, index);"
      , "      if (kind == 10) pudu_binary_pairs(out, node->fields[2].box, depth);"
      , "      else pudu_binary_keyed(out, node->fields[2].box, depth);"
      , "      break;"
      , "    default: out->failed = 1; break;"
      , "  }"
      , "}"
      , "/* The tree as bytes: the name table, then the root node. No box when a"
      , "   shape, a count or the nesting is outside what the form carries. */"
      , "static pudu_box *pudu_binary_encode(pudu_box *node, int whole, int real, int flag, int text, int raw, int reals, int items,"
      , "    int absent, int present, int fields, int choice, int record, int picked) {"
      , "  pudu_binary_writer out = {NULL, 0, 0, NULL, 0, 0, NULL, 0, NULL, 0,"
      , "    {whole, real, flag, text, raw, reals, items, absent, present, fields, choice, record, picked}, 0};"
      , "  pudu_box *made = NULL;"
      , "  pudu_binary_node(&out, node, 0);"
      , "  if (!out.failed) {"
      , "    size_t header = 4;"
      , "    unsigned char *bytes, *cursor;"
      , "    pudu_text packed;"
      , "    for (size_t i = 0; i < out.named; ++i) {"
      , "      if (header > SIZE_MAX - 4 || out.names[i].length > SIZE_MAX - header - 4) pudu_memory_failure();"
      , "      header += 4 + out.names[i].length;"
      , "    }"
      , "    if (out.length > SIZE_MAX - header) pudu_memory_failure();"
      , "    packed = pudu_text_allocate(header + out.length, &bytes);"
      , "    cursor = bytes;"
      , "    pudu_binary_store(cursor, (uint32_t)out.named);"
      , "    cursor += 4;"
      , "    for (size_t i = 0; i < out.named; ++i) {"
      , "      pudu_binary_store(cursor, (uint32_t)out.names[i].length);"
      , "      if (out.names[i].length != 0) memcpy(cursor + 4, out.names[i].bytes, out.names[i].length);"
      , "      cursor += 4 + out.names[i].length;"
      , "    }"
      , "    if (out.length != 0) memcpy(cursor, out.bytes, out.length);"
      , "    made = pudu_bytes_wrap(packed);"
      , "  }"
      , "  free(out.bytes);"
      , "  free(out.names);"
      , "  free(out.slots);"
      , "  free(out.seen);"
      , "  return made;"
      , "}"
      ])
  , ("binary_decode", ["binary_wire", "array", "tree_insert", "text_allocate", "text_retain", "bytes_wrap", "utf8_valid", "kernel_int", "kernel_signed", "host_status", "host_done"],
      [ "static inline uint32_t pudu_binary_word(const unsigned char *b) {"
      , "  return (uint32_t)b[0] | (uint32_t)b[1] << 8 | (uint32_t)b[2] << 16 | (uint32_t)b[3] << 24;"
      , "}"
      , "static inline uint64_t pudu_binary_wide(const unsigned char *b) {"
      , "  uint64_t value = 0;"
      , "  for (int i = 7; i >= 0; --i) value = value << 8 | b[i];"
      , "  return value;"
      , "}"
      , "/* The bytes, where each name is spelled, the first name spelled like each"
      , "   one, which record last held each name, and the Node variants' indexes."
      , "   A reader walks the bytes twice: once to accept them, once to build, so"
      , "   nothing built is ever abandoned. */"
      , "typedef struct {"
      , "  const unsigned char *bytes; size_t size;"
      , "  size_t named; size_t *spelled; uint32_t *same;"
      , "  size_t *seen; size_t record;"
      , "  pudu_text *texts;"
      , "  int tags[13];"
      , "  const pudu_tree_ops *ops; pudu_box *(*wrap)(pudu_tree_node *);"
      , "} pudu_binary_reader;"
      , "/* What the host says of refused bytes: three pieces joined. */"
      , "static void pudu_binary_refuse(const char *before, const unsigned char *middle, size_t length, const char *after) {"
      , "  size_t head = strlen(before), tail = strlen(after);"
      , "  unsigned char *bytes;"
      , "  pudu_text_release(pudu_host_said);"
      , "  pudu_host_said = pudu_text_allocate(head + length + tail, &bytes);"
      , "  memcpy(bytes, before, head);"
      , "  if (length != 0) memcpy(bytes + head, middle, length);"
      , "  memcpy(bytes + head + length, after, tail);"
      , "  pudu_host_status = 1;"
      , "}"
      , "static void pudu_binary_refuse_number(const char *before, unsigned long long value, const char *after) {"
      , "  char digits[24];"
      , "  int length = snprintf(digits, sizeof digits, \"%llu\", value);"
      , "  pudu_binary_refuse(before, (const unsigned char *)digits, (size_t)length, after);"
      , "}"
      , "static int pudu_binary_need(const pudu_binary_reader *in, size_t at, size_t count) {"
      , "  if (at > in->size || count > in->size - at) { pudu_binary_refuse(\"the bytes end inside a node\", NULL, 0, \"\"); return 0; }"
      , "  return 1;"
      , "}"
      , "/* The name table: every name must lie inside the bytes and be UTF-8."
      , "   Names spelled alike share the first one's index, so a field is known"
      , "   by its spelling. */"
      , "static int pudu_binary_names(pudu_binary_reader *in, size_t *next) {"
      , "  size_t at = 4, room = 0, slotted = 16;"
      , "  uint32_t count, *slots;"
      , "  if (!pudu_binary_need(in, 0, 4)) return 0;"
      , "  count = pudu_binary_word(in->bytes);"
      , "  for (uint32_t i = 0; i < count; ++i) {"
      , "    uint32_t length;"
      , "    if (!pudu_binary_need(in, at, 4)) return 0;"
      , "    length = pudu_binary_word(in->bytes + at);"
      , "    if (!pudu_binary_need(in, at + 4, length)) return 0;"
      , "    if (!pudu_utf8_valid(in->bytes + at + 4, length)) { pudu_binary_refuse(\"text that is not UTF-8\", NULL, 0, \"\"); return 0; }"
      , "    if (in->named == room) {"
      , "      room = room < 16 ? 16 : room * 2;"
      , "      in->spelled = pudu_binary_grow(in->spelled, room, sizeof *in->spelled);"
      , "    }"
      , "    in->spelled[in->named] = at;"
      , "    in->named += 1;"
      , "    at += 4 + (size_t)length;"
      , "  }"
      , "  while (slotted < in->named * 2) slotted *= 2;"
      , "  slots = calloc(slotted, sizeof *slots);"
      , "  in->same = pudu_binary_grow(NULL, in->named, sizeof *in->same);"
      , "  in->seen = calloc(in->named == 0 ? 1 : in->named, sizeof *in->seen);"
      , "  if (slots == NULL || in->seen == NULL) pudu_memory_failure();"
      , "  for (size_t i = 0; i < in->named; ++i) {"
      , "    const unsigned char *name = in->bytes + in->spelled[i] + 4;"
      , "    size_t length = pudu_binary_word(in->bytes + in->spelled[i]);"
      , "    size_t slot = (size_t)pudu_binary_hash(name, length) & (slotted - 1);"
      , "    for (;;) {"
      , "      size_t other;"
      , "      if (slots[slot] == 0) { slots[slot] = (uint32_t)i + 1; in->same[i] = (uint32_t)i; break; }"
      , "      other = slots[slot] - 1;"
      , "      if (pudu_binary_same(in->bytes + in->spelled[other] + 4, pudu_binary_word(in->bytes + in->spelled[other]), name, length)) {"
      , "        in->same[i] = (uint32_t)other;"
      , "        break;"
      , "      }"
      , "      slot = (slot + 1) & (slotted - 1);"
      , "    }"
      , "  }"
      , "  free(slots);"
      , "  *next = at;"
      , "  return 1;"
      , "}"
      , "static int pudu_binary_check(pudu_binary_reader *in, int depth, size_t at, size_t *next);"
      , "/* A record's fields: each name index inside the table, no name twice."
      , "   Each name's earlier mark is put back at the end, so an enclosing"
      , "   record still knows its own names. */"
      , "static int pudu_binary_check_fields(pudu_binary_reader *in, int depth, size_t at, size_t *next) {"
      , "  size_t record, held = 0, room = 0;"
      , "  size_t *names = NULL, *before = NULL;"
      , "  uint32_t count;"
      , "  int accepted = 1;"
      , "  if (!pudu_binary_need(in, at, 4)) return 0;"
      , "  count = pudu_binary_word(in->bytes + at);"
      , "  at += 4;"
      , "  record = ++in->record;"
      , "  for (uint32_t i = 0; accepted && i < count; ++i) {"
      , "    uint32_t index;"
      , "    size_t name;"
      , "    if (!pudu_binary_need(in, at, 4)) { accepted = 0; break; }"
      , "    index = pudu_binary_word(in->bytes + at);"
      , "    if (index >= in->named) { pudu_binary_refuse_number(\"a name index \", index, \" past the name table\"); accepted = 0; break; }"
      , "    name = in->same[index];"
      , "    if (in->seen[name] == record) {"
      , "      pudu_binary_refuse(\"the field \", in->bytes + in->spelled[name] + 4, pudu_binary_word(in->bytes + in->spelled[name]), \" appears twice\");"
      , "      accepted = 0;"
      , "      break;"
      , "    }"
      , "    if (held == room) {"
      , "      room = room < 8 ? 8 : room * 2;"
      , "      names = pudu_binary_grow(names, room, sizeof *names);"
      , "      before = pudu_binary_grow(before, room, sizeof *before);"
      , "    }"
      , "    names[held] = name;"
      , "    before[held] = in->seen[name];"
      , "    held += 1;"
      , "    in->seen[name] = record;"
      , "    accepted = pudu_binary_check(in, depth, at + 4, &at);"
      , "  }"
      , "  while (held > 0) { held -= 1; in->seen[names[held]] = before[held]; }"
      , "  free(names);"
      , "  free(before);"
      , "  *next = at;"
      , "  return accepted;"
      , "}"
      , "/* One node at a position, by its wire tag. Every length is checked"
      , "   against the bytes left before anything reads them. */"
      , "static int pudu_binary_check(pudu_binary_reader *in, int depth, size_t at, size_t *next) {"
      , "  unsigned char tag;"
      , "  uint32_t count;"
      , "  if (depth > 512) { pudu_binary_refuse(\"nodes nest deeper than 512\", NULL, 0, \"\"); return 0; }"
      , "  if (!pudu_binary_need(in, at, 1)) return 0;"
      , "  tag = in->bytes[at];"
      , "  at += 1;"
      , "  switch (tag) {"
      , "    case 0: case 1:"
      , "      if (!pudu_binary_need(in, at, 8)) return 0;"
      , "      *next = at + 8;"
      , "      return 1;"
      , "    case 2:"
      , "      if (!pudu_binary_need(in, at, 1)) return 0;"
      , "      if (in->bytes[at] > 1) { pudu_binary_refuse(\"a flag byte above 1\", NULL, 0, \"\"); return 0; }"
      , "      *next = at + 1;"
      , "      return 1;"
      , "    case 3: case 4:"
      , "      if (!pudu_binary_need(in, at, 4)) return 0;"
      , "      count = pudu_binary_word(in->bytes + at);"
      , "      if (!pudu_binary_need(in, at + 4, count)) return 0;"
      , "      if (tag == 3 && !pudu_utf8_valid(in->bytes + at + 4, count)) { pudu_binary_refuse(\"text that is not UTF-8\", NULL, 0, \"\"); return 0; }"
      , "      *next = at + 4 + (size_t)count;"
      , "      return 1;"
      , "    case 5:"
      , "      if (!pudu_binary_need(in, at, 4)) return 0;"
      , "      count = pudu_binary_word(in->bytes + at);"
      , "      if ((uint64_t)count > (in->size - (at + 4)) / 8) {"
      , "        pudu_binary_refuse(\"the bytes end inside a node\", NULL, 0, \"\");"
      , "        return 0;"
      , "      }"
      , "      *next = at + 4 + (size_t)count * 8;"
      , "      return 1;"
      , "    case 6:"
      , "      if (!pudu_binary_need(in, at, 4)) return 0;"
      , "      count = pudu_binary_word(in->bytes + at);"
      , "      at += 4;"
      , "      for (uint32_t i = 0; i < count; ++i) if (!pudu_binary_check(in, depth + 1, at, &at)) return 0;"
      , "      *next = at;"
      , "      return 1;"
      , "    case 7: *next = at; return 1;"
      , "    case 8: return pudu_binary_check(in, depth + 1, at, next);"
      , "    case 9: return pudu_binary_check_fields(in, depth + 1, at, next);"
      , "    case 10:"
      , "      if (!pudu_binary_need(in, at, 4)) return 0;"
      , "      count = pudu_binary_word(in->bytes + at);"
      , "      if (count >= in->named) { pudu_binary_refuse_number(\"a name index \", count, \" past the name table\"); return 0; }"
      , "      return pudu_binary_check_fields(in, depth + 1, at + 4, next);"
      , "    default:"
      , "      pudu_binary_refuse_number(\"an unknown node tag \", tag, \"\");"
      , "      return 0;"
      , "  }"
      , "}"
      , "static pudu_box *pudu_binary_sum(int tag, size_t members) {"
      , "  pudu_box *box = pudu_box_new(1 + members);"
      , "  box->fields[0].scalar = tag;"
      , "  return box;"
      , "}"
      , "static pudu_text pudu_binary_text(const unsigned char *source, size_t length) {"
      , "  unsigned char *bytes;"
      , "  pudu_text text = pudu_text_allocate(length, &bytes);"
      , "  if (length != 0) memcpy(bytes, source, length);"
      , "  return text;"
      , "}"
      , "static pudu_box *pudu_binary_build(pudu_binary_reader *in, size_t at, size_t *next);"
      , "/* Accepted fields as a map from name to node; the tree takes each key"
      , "   and value it is handed. */"
      , "static pudu_box *pudu_binary_fields(pudu_binary_reader *in, size_t at, size_t *next) {"
      , "  uint32_t count = pudu_binary_word(in->bytes + at);"
      , "  pudu_tree_node *root = NULL;"
      , "  at += 4;"
      , "  for (uint32_t i = 0; i < count; ++i) {"
      , "    pudu_cell key, value;"
      , "    key.text = pudu_text_retain(in->texts[pudu_binary_word(in->bytes + at)]);"
      , "    value.box = pudu_binary_build(in, at + 4, &at);"
      , "    root = pudu_tree_insert(root, key, value, 1, in->ops);"
      , "  }"
      , "  *next = at;"
      , "  return in->wrap(root);"
      , "}"
      , "/* The node at a position; only called on bytes already accepted. */"
      , "static pudu_box *pudu_binary_build(pudu_binary_reader *in, size_t at, size_t *next) {"
      , "  unsigned char tag = in->bytes[at];"
      , "  pudu_box *made;"
      , "  uint32_t count;"
      , "  at += 1;"
      , "  switch (tag) {"
      , "    case 0:"
      , "      made = pudu_binary_sum(in->tags[0], 1);"
      , "      made->fields[1].integer = pudu_kernel_int(pudu_kernel_signed(pudu_binary_wide(in->bytes + at)));"
      , "      *next = at + 8;"
      , "      return made;"
      , "    case 1:"
      , "      made = pudu_binary_sum(in->tags[1], 1);"
      , "      made->fields[1].floating = pudu_binary_wide(in->bytes + at);"
      , "      *next = at + 8;"
      , "      return made;"
      , "    case 2:"
      , "      made = pudu_binary_sum(in->tags[2], 1);"
      , "      made->fields[1].scalar = in->bytes[at];"
      , "      *next = at + 1;"
      , "      return made;"
      , "    case 3:"
      , "      count = pudu_binary_word(in->bytes + at);"
      , "      made = pudu_binary_sum(in->tags[3], 1);"
      , "      made->fields[1].text = pudu_binary_text(in->bytes + at + 4, count);"
      , "      *next = at + 4 + (size_t)count;"
      , "      return made;"
      , "    case 4: case 5: {"
      , "      size_t width;"
      , "      count = pudu_binary_word(in->bytes + at);"
      , "      width = tag == 4 ? (size_t)count : (size_t)count * 8;"
      , "      made = pudu_binary_sum(in->tags[tag], 1);"
      , "      made->fields[1].box = pudu_bytes_wrap(pudu_binary_text(in->bytes + at + 4, width));"
      , "      *next = at + 4 + width;"
      , "      return made;"
      , "    }"
      , "    case 6: {"
      , "      pudu_box *members;"
      , "      count = pudu_binary_word(in->bytes + at);"
      , "      at += 4;"
      , "      members = pudu_array_new(count);"
      , "      for (uint32_t i = 0; i < count; ++i) members->fields[0].items->cells[i].box = pudu_binary_build(in, at, &at);"
      , "      pudu_array_length(members) = count;"
      , "      made = pudu_binary_sum(in->tags[6], 1);"
      , "      made->fields[1].box = members;"
      , "      *next = at;"
      , "      return made;"
      , "    }"
      , "    case 7:"
      , "      *next = at;"
      , "      return pudu_binary_sum(in->tags[7], 0);"
      , "    case 8:"
      , "      made = pudu_binary_sum(in->tags[8], 1);"
      , "      made->fields[1].box = pudu_binary_build(in, at, next);"
      , "      return made;"
      , "    case 9:"
      , "      made = pudu_binary_sum(in->tags[11], 1);"
      , "      made->fields[1].box = pudu_binary_fields(in, at, next);"
      , "      return made;"
      , "    default:"
      , "      made = pudu_binary_sum(in->tags[12], 2);"
      , "      made->fields[1].text = pudu_text_retain(in->texts[pudu_binary_word(in->bytes + at)]);"
      , "      made->fields[2].box = pudu_binary_fields(in, at + 4, next);"
      , "      return made;"
      , "  }"
      , "}"
      , "/* The node tree the bytes hold, or no box and what was wrong with them."
      , "   Fields read back as Record and a choice as Picked. */"
      , "static pudu_box *pudu_binary_decode(pudu_box *source, int whole, int real, int flag, int text, int raw, int reals, int items,"
      , "    int absent, int present, int fields, int choice, int record, int picked,"
      , "    const pudu_tree_ops *ops, pudu_box *(*wrap)(pudu_tree_node *)) {"
      , "  pudu_binary_reader in = {source->fields[0].text.bytes, source->fields[0].text.length, 0, NULL, NULL, NULL, 0, NULL,"
      , "    {whole, real, flag, text, raw, reals, items, absent, present, fields, choice, record, picked}, ops, wrap};"
      , "  size_t root = 0, end = 0;"
      , "  pudu_box *made = NULL;"
      , "  if (pudu_binary_names(&in, &root) && pudu_binary_check(&in, 0, root, &end)) {"
      , "    if (end != in.size) pudu_binary_refuse_number(\"\", (unsigned long long)(in.size - end), \" bytes follow the root node\");"
      , "    else {"
      , "      in.texts = pudu_binary_grow(NULL, in.named, sizeof *in.texts);"
      , "      for (size_t i = 0; i < in.named; ++i)"
      , "        in.texts[i] = pudu_binary_text(in.bytes + in.spelled[i] + 4, pudu_binary_word(in.bytes + in.spelled[i]));"
      , "      made = pudu_binary_build(&in, root, &end);"
      , "      for (size_t i = 0; i < in.named; ++i) pudu_text_release(in.texts[i]);"
      , "      free(in.texts);"
      , "      pudu_host_done(0);"
      , "    }"
      , "  }"
      , "  free(in.spelled);"
      , "  free(in.same);"
      , "  free(in.seen);"
      , "  return made;"
      , "}"
      ])
  ]
